code_sketch:
countdown = Enumerator.produce(8) { |n| n > 1 ? n / 2 : raise(StopIteration) }
countdown.first(3)                       # => [8, 4, 2]

# manual form: several layers per state, bounded by the caller
pairs = Enumerator.new { |y| 0.step(by: 2) { |n| y << n } }
pairs.lazy.select(&:even?).first(3)      # => [0, 2, 4]
